package cn.workbench;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.mock.web.MockHttpServletRequest;
import java.util.*;
import static cn.workbench.Records.map;
import static org.assertj.core.api.Assertions.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:calendar;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1","task.bootstrap-password=TestOnly-Synthetic12345","task.totp-key=AAECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaGxwdHh8="})
@org.springframework.test.context.TestExecutionListeners(value={org.springframework.test.context.support.DependencyInjectionTestExecutionListener.class,org.springframework.test.context.transaction.TransactionalTestExecutionListener.class},mergeMode=org.springframework.test.context.TestExecutionListeners.MergeMode.REPLACE_DEFAULTS)
@ActiveProfiles("test") @Transactional class CalendarSimulationTest {
 @Autowired JdbcTemplate jdbc;@Autowired CalendarSimulationController controller;@Autowired TaskService tasks;@Autowired Records records;@Autowired Jsons json;@Autowired KpiController kpi;
 MockHttpServletRequest request(long uid,long scope,String path){var q=new MockHttpServletRequest("POST","/api/v1"+path);q.addHeader("Idempotency-Key",UUID.randomUUID().toString());q.getSession().setAttribute("uid",uid);q.getSession().setAttribute("scopeId",scope);q.getSession().setAttribute("totpAt",System.currentTimeMillis());return q;}
 Map<String,Object> data(Object envelope){return (Map<String,Object>)((Map<?,?>)envelope).get("data");}
 Map<String,Object> calendar(){return map("mode","WORKING_TIME","weekendDays",List.of(0,6),"dayStart","09:00","dayEnd","18:00","holidays",List.of("2020-01-01"),"workingDates",List.of(),"leaves",List.of());}
 Map<String,Object> simulation(){return map("companyId",1,"period","2020-01","calendarVersionId",0,"templateId",0,"simulation",true,"reason","Synthetic calendar comparison");}
 @Test void draftTasksDoNotEnterCalendarSimulation(){
  var leader=new Policy.Actor(2,"COMPANY_LEADER",1,null,2);var task=tasks.create(leader,map("title","Draft calendar boundary","content","Synthetic","companyId",1,"hostDeptId",3,"collaboratorDeptIds",List.of(),"deadline","2030-01-10T00:00:00Z"));
  var sub=records.children(Jsons.number(task.get("id")),"SUB_TASK").getFirst();sub.put("deadline","2020-01-10T00:00:00Z");records.save(sub);
  var result=data(controller.simulate(request(2,2,"/kpi/calendar-simulations"),simulation()));var rows=(List<Map<String,Object>>)result.get("rows");assertThat(rows).filteredOn(row->Jsons.integer(row.get("deptId"))==3).singleElement().satisfies(row->assertThat(row.get("sampleCount")).isEqualTo(0));
 }
 @Test void draftTasksAreExcludedFromFormalAndCalendarKpiInputs(){
  var leader=new Policy.Actor(2,"COMPANY_LEADER",1,null,2);var admin=new Policy.Actor(1,"ADMIN",1,null,1);
  var task=tasks.create(leader,map("title","Draft KPI boundary","content","Synthetic","companyId",1,"hostDeptId",3,"collaboratorDeptIds",List.of(),"deadline","2030-01-10T00:00:00Z"));
  long taskId=Jsons.number(task.get("id"));var sub=records.children(taskId,"SUB_TASK").getFirst();sub.put("deadline","2020-01-10T00:00:00Z");records.save(sub);
  var template=records.list("KPI_TEMPLATE",null,null).getFirst();var request=map("companyId",1,"period","2020-01","templateId",template.get("id"),"simulation",false);
  var draftRun=(Map<String,Object>)kpi.run(admin,request);var draftInputs=(List<?>)json.map(String.valueOf(draftRun.get("inputSnapshot"))).get("subTasks");assertThat(draftInputs).isEmpty();
  var draftCalendar=data(controller.simulate(request(2,2,"/kpi/calendar-simulations"),simulation()));var draftRows=(List<Map<String,Object>>)draftCalendar.get("rows");assertThat(draftRows).filteredOn(row->Jsons.integer(row.get("deptId"))==3).singleElement().satisfies(row->assertThat(row.get("sampleCount")).isEqualTo(0));
  tasks.taskAction(leader,taskId,"confirm-assign",Map.of());
  assertThat(json.map(String.valueOf(records.get(Jsons.number(draftRun.get("id"))).get("inputSnapshot"))).get("subTasks")).isEqualTo(draftInputs);request.put("simulation",true);
  var confirmedRun=(Map<String,Object>)kpi.run(admin,request);var confirmedInputs=(List<?>)json.map(String.valueOf(confirmedRun.get("inputSnapshot"))).get("subTasks");assertThat(confirmedInputs).hasSize(1);
  var confirmedCalendar=data(controller.simulate(request(2,2,"/kpi/calendar-simulations"),simulation()));var confirmedRows=(List<Map<String,Object>>)confirmedCalendar.get("rows");assertThat(confirmedRows).filteredOn(row->Jsons.integer(row.get("deptId"))==3).singleElement().satisfies(row->assertThat(row.get("sampleCount")).isEqualTo(1));
 }
 @Test void candidateCalendarsAndSimulationsHaveIndependentAppendOnlyStorage(){assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM information_schema.tables WHERE LOWER(table_name) IN ('company_calendar_version','kpi_simulation_template','task_classification_version','calendar_simulation')",Integer.class)).isEqualTo(4);}
 @Test void calendarVersionRequiresExpectedVersionAndScopedAdmin(){var body=map("companyId",1,"name","Synthetic calendar","reason","Synthetic reason","expectedVersion",0,"calendar",calendar());var created=data(controller.createCalendar(request(1,1,"/kpi/calendar-versions"),body));assertThat(created.get("version")).isEqualTo(1);assertThatThrownBy(()->controller.createCalendar(request(1,1,"/kpi/calendar-versions"),body)).isInstanceOf(ApiException.class).extracting("code").isEqualTo("CONFLICT");assertThatThrownBy(()->controller.createCalendar(request(2,2,"/kpi/calendar-versions"),body)).isInstanceOf(ApiException.class);}
 @Test void foreignDepartmentLeaveIsRejected(){var calendar=calendar();calendar.put("leaves",List.of(map("deptId",5,"from","2020-01-02T10:00:00+08:00","to","2020-01-02T16:00:00+08:00")));assertThatThrownBy(()->controller.createCalendar(request(1,1,"/kpi/calendar-versions"),map("companyId",1,"name","Synthetic","reason","Synthetic","expectedVersion",0,"calendar",calendar))).isInstanceOf(ApiException.class);}
 @Test void headsCannotSimulateOtherDepartmentAndAdminCannotReadBusinessResults(){var body=simulation();body.put("deptId",4);assertThatThrownBy(()->controller.simulate(request(3,3,"/kpi/calendar-simulations"),body)).isInstanceOf(ApiException.class);assertThatThrownBy(()->controller.simulate(request(1,1,"/kpi/calendar-simulations"),simulation())).isInstanceOf(ApiException.class);}
 @Test void simulationNeverCreatesFormalRunsAndOldResultSurvivesTaskChanges(){var leader=new Policy.Actor(2,"COMPANY_LEADER",1,null,2);var task=tasks.create(leader,map("title","Synthetic calendar task","content","Synthetic","companyId",1,"hostDeptId",3,"collaboratorDeptIds",List.of(),"deadline","2030-01-10T00:00:00Z"));tasks.taskAction(leader,Jsons.number(task.get("id")),"confirm-assign",Map.of());var sub=records.children(Jsons.number(task.get("id")),"SUB_TASK").getFirst();sub.put("deadline","2020-01-10T00:00:00Z");sub.put("status","ACCEPTED");sub.put("submittedAt","2020-01-09T00:00:00Z");sub.put("firstReceivedAt","2020-01-08T00:00:00Z");sub.put("dispatchedAt","2020-01-08T00:00:00Z");sub.put("everOverdue",false);sub.put("rejectCount",0);records.save(sub);long formalBefore=jdbc.queryForObject("SELECT COUNT(*) FROM kpi_run",Long.class);var simulated=data(controller.simulate(request(2,2,"/kpi/calendar-simulations"),simulation()));assertThat((List<Map<String,Object>>)simulated.get("rows")).filteredOn(row->Jsons.integer(row.get("deptId"))==3).singleElement().satisfies(row->assertThat(row.get("sampleCount")).isEqualTo(1));long id=Jsons.number(simulated.get("id"));var old=data(controller.simulation(request(2,2,"/kpi/calendar-simulations/"+id),id));sub.put("submittedAt","2020-02-20T00:00:00Z");records.save(sub);var after=data(controller.simulation(request(2,2,"/kpi/calendar-simulations/"+id),id));assertThat(json.write(after)).isEqualTo(json.write(old));assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM kpi_run",Long.class)).isEqualTo(formalBefore);assertThatThrownBy(()->controller.simulation(request(3,3,"/kpi/calendar-simulations/"+id),id)).isInstanceOf(ApiException.class);}
 @Test void candidateTemplateCannotPublishAndClassificationVersionsConflict(){var candidate=map("companyId",1,"name","Synthetic candidate","reason","Synthetic reason","weights",List.of(40,15,20,10,15),"complexityWeights",map("SIMPLE",1,"NORMAL",1,"COMPLEX",2),"simulation",false);assertThatThrownBy(()->controller.createTemplate(request(1,1,"/kpi/simulation-templates"),candidate)).isInstanceOf(ApiException.class);candidate.put("simulation",true);assertThat(data(controller.createTemplate(request(1,1,"/kpi/simulation-templates"),candidate)).get("simulation")).isEqualTo(true);var task=tasks.create(new Policy.Actor(2,"COMPANY_LEADER",1,null,2),map("title","Classification task","content","Synthetic","companyId",1,"hostDeptId",3,"collaboratorDeptIds",List.of(),"deadline","2030-01-10T00:00:00Z"));long id=Jsons.number(task.get("id"));var body=map("complexity","COMPLEX","category","PROJECT","expectedVersion",0,"reason","Synthetic classification");assertThat(data(controller.classify(request(2,2,"/tasks/"+id+"/classification"),id,body)).get("version")).isEqualTo(1);assertThatThrownBy(()->controller.classify(request(2,2,"/tasks/"+id+"/classification"),id,body)).isInstanceOf(ApiException.class).extracting("code").isEqualTo("CONFLICT");}
}
